export const TOTAL_US_COUNTIES_COUNT = 3143;

// Fast O(1) lookup map by 5-digit FIPS code across all 3,143 US counties
export const COUNTY_BY_FIPS: Record<string, CountyItem & { stateSlug: string }> = (() => {
  const map: Record<string, CountyItem & { stateSlug: string }> = {};
  for (const [stateSlug, list] of Object.entries(COUNTIES_BY_STATE)) {
    for (const c of list) {
      map[c.fips] = { ...c, stateSlug };
    }
  }
  return map;
})();

export function getCountyElectionAuthorityTitle(stateCode: string, countyName: string): string {
  switch (stateCode) {
    case 'FL':
      return `${countyName} Supervisor of Elections`;
    case 'TX':
      return `${countyName} Elections Administrator & Voter Registrar`;
    case 'PA':
    case 'OH':
    case 'NC':
    case 'NY':
    case 'IL':
    case 'MD':
      return `${countyName} Board of Elections`;
    case 'GA':
      return `${countyName} Board of Registrations and Elections`;
    case 'CA':
      return `${countyName} Registrar of Voters / County Clerk`;
    case 'AZ':
    case 'NV':
      return `${countyName} Recorder & Elections Department`;
    case 'LA':
      return `${countyName} Registrar of Voters & Clerk of Court`;
    case 'MI':
    case 'WI':
    case 'NJ':
    case 'MO':
    case 'CO':
    case 'UT':
      return `${countyName} Clerk & Elections Division`;
    case 'VA':
      return `${countyName} General Registrar & Electoral Board`;
    default:
      return `${countyName} Election Office & Voter Registrar`;
  }
}

